    ok("!! the tables list the right arms: the means list all 24 (autopilot first), the per-arm gains and the LOST, EXTRA POWER and PRICED GAIN lists leave the autopilot out, law0 prints a +0.0000 gain with its sign, the AUDIT line starts with the autopilot, and the headers say 0.02, 0.005 / 0.02 / 0.04 and lost runs of 400", (() => { const R = X.report(mkAu()), at = R.findIndex((l) => l.startsWith("per arm:")), bl2 = X.bottomLines(mkAu()); return R.slice(R.findIndex((l) => l.startsWith("means")) + 1, at).map((l) => l.trim().split(/\s+/)[0]).join() === X.ARM_IDS.join() && R[at + 1].startsWith("  law0       +0.0000 / +0.0000") && R.slice(at + 1, at + 24).map((l) => l.trim().split(/\s+/)[0]).join() === X.ARM_IDS.slice(1).join() && bl2[7].startsWith("LOST (runs lost of 400): law0 0, c02 0") && bl2[8].startsWith("EXTRA POWER (mean of dark and lit extra kW): c02 ") && bl2[9].includes("PENALISED PRICED GAIN (at 0.005 / 0.02 / 0.04): c02 ") && bl2[6].startsWith("AUDIT (dark / lit mean score, dark mean power, mean dark thrust): autopilot ") && /penalised priced score at 0\.02/.test(R[0]) && R.some((l) => l === "per arm: dark / lit gain over the autopilot, extra power (kW, dark / lit), penalised priced gain at 0.005 / 0.02 / 0.04:") && R.some((l) => l === "means (dark score / lit score; dark mean power kW; lit mean power kW; lost runs of 400):") && R.some((l) => l.startsWith("  autopilot  0.")) && !/unpenalised priced gain autopilot/.test(bl2[13]); })());
