    ok("!! a law or a network with ONE non-finite weight is refused in st39 (A02 and B02) and in h27's law; armsOf names the rule", (() => { const one = (v) => { const w = w963(0.5); w[400] = v; return w; }; return ["A02", "B02"].every((g) => /st39\.[AB]02 is four 963-weight vectors/.test(thr(() => X.armsOf(WIP, h27, s32, { ...st39, [g]: st39[g].map((w, i) => (i === 1 ? one(NaN) : w)) }, fresh)))) && /h27 is \{ laws: one 4-weight law \}/.test(thr(() => X.armsOf(WIP, { laws: [[1, NaN, 2, 3]] }, s32, st39, fresh))); })());
